    // trigger(), never these values.
    uint64_t v_done_last = 0, a_done_last = 0;

    static const long WATCHDOG_CYCLES = 200000L;   // ~10x a 4 KiB copy + walk
    static const long CFG_TIMEOUT     = 100000L;
    // Per-delay cap, enforced by argument validation before simulation.
    static const long BUDGET_DELAY_CAP = 2000000L;

    Tb() : top(new TopT) {}
    ~Tb() {
#ifdef ACTUAL_DMA_SYSTEM
        if (event_trace) std::fclose(event_trace);
#endif
        top->final(); delete top;
    }
#ifdef ACTUAL_DMA_SYSTEM
    void trace_event(const char* event, unsigned tag, uint64_t addr, uint64_t value) {
        // The legacy trace is a WINDOW-relative timeline.  In full-batch mode
        // the full trace block emits a t0-relative timeline into the same
        // file, so the legacy trace is disabled there to keep exactly one time
        // base per file.
        if (event_trace && win_open && !full_era)
            std::fprintf(event_trace, "%ld,%s,%u,%llu,%llu\n",
                g_cycle - win_open_cycle, event, tag,
                (unsigned long long)addr, (unsigned long long)value);
    }
#endif

    // ---------------------------------------------------------------------
    // memory helpers (identical to coupled harness)
    // ---------------------------------------------------------------------
    void write64(uint64_t addr, uint64_t data) {
        for (int i = 0; i < 8; ++i)
            mem[addr + i] = (uint8_t)((data >> (8 * i)) & 0xFF);
    }
    uint64_t read64(uint64_t addr) {
        uint64_t data = 0;
        for (int i = 0; i < 8; ++i) {
            auto it = mem.find(addr + i);
            if (it == mem.end()) fail("unmapped read", __FILE__, __LINE__);
            data |= (uint64_t)it->second << (8 * i);
        }
        if(transport_trace) std::fprintf(transport_trace,"%ld,read,%llu,8,255,%llu\n",g_cycle,(unsigned long long)addr,(unsigned long long)data);
        return data;
    }
    void write_beat(uint64_t addr, uint64_t data, uint8_t strb) {
        if(transport_trace) std::fprintf(transport_trace,"%ld,write,%llu,8,%u,%llu\n",g_cycle,(unsigned long long)addr,unsigned(strb),(unsigned long long)data);
        for (int i = 0; i < 8; ++i)
            if (strb & (1 << i))
                mem[addr + i] = (uint8_t)((data >> (8 * i)) & 0xFF);
    }

    // ---------------------------------------------------------------------
    // devices / page tables (identical to coupled harness + A ring)
    // ---------------------------------------------------------------------
    void setup_memory(uint32_t ap) {
        mem.clear();
        a_pages = ap;

        // Extended 1-level DDT at 0x10000, stride 64. DID10 -> 0x10280, DID11 -> 0x102C0.
        write64(0x10280, 0x0000000000000001ULL);
        write64(0x10288, 0x0000000000000000ULL);
        write64(0x10290, 0x000000000000A000ULL);
        write64(0x10298, 0x8000000000000020ULL); // Sv39, V root 0x20000
        write64(0x102A0, 0x0ULL); write64(0x102A8, 0x0ULL);
        write64(0x102B0, 0x0ULL); write64(0x102B8, 0x0ULL);

        write64(0x102C0, 0x0000000000000001ULL);
        write64(0x102C8, 0x0000000000000000ULL);
        write64(0x102D0, 0x000000000000B000ULL);
        write64(0x102D8, 0x8000000000000030ULL); // Sv39, A root 0x30000
        write64(0x102E0, 0x0ULL); write64(0x102E8, 0x0ULL);
        write64(0x102F0, 0x0ULL); write64(0x102F8, 0x0ULL);

        // V page tables: root 0x20000, L1V 0x40000, L0V 0x50000.
        write64(0x20000, 0x0000000000010001ULL);
        write64(0x40400, 0x0000000000014001ULL);
        write64(0x50000, 0x00000000200000DFULL); // Vsrc -> 0x80000000
        write64(0x50008, 0x00000000200004DFULL); // Vdst -> 0x80001000
        write64(0x50010, ((V_COLD_DST_PA >> 12) << 10) | 0xDFULL); // Vcold-dst -> 0x80002000

        // A page tables: root 0x30000, L1A 0x60000, L0A 0x70000.
        write64(0x30000, 0x0000000000018001ULL);
        write64(0x60800, 0x000000000001C001ULL);
        for (uint32_t n = 0; n < 2 * a_pages; ++n) {
            uint64_t pa = (n < a_pages)
                        ? (A_SRC_PA_BASE + (uint64_t)n * 0x1000)
                        : (A_DST_PA_BASE + (uint64_t)(n - a_pages) * 0x1000);
            write64(0x70000 + (uint64_t)n * 8, ((pa >> 12) << 10) | 0xDFULL);
        }

        // V source content + unique destination pre-fill.
        for (uint32_t i = 0; i < PAGE_BEATS; ++i) {
            write64(V_SRC_PA + (uint64_t)i * 8, page_word(0, i));
            write64(V_DST_PA + (uint64_t)i * 8, page_old(0, i));
            write64(V_COLD_DST_PA + (uint64_t)i * 8, page_old(0, i));
        }
        // A source content + unique destination pre-fill.
        for (uint32_t p = 0; p < a_pages; ++p) {
            for (uint32_t i = 0; i < PAGE_BEATS; ++i) {
                write64(A_SRC_PA_BASE + (uint64_t)p * 0x1000 + (uint64_t)i * 8,
                        page_word(1 + p, i));
                write64(A_DST_PA_BASE + (uint64_t)p * 0x1000 + (uint64_t)i * 8,
                        page_old(1 + p, i));
            }
        }

#ifdef ACTUAL_DMA_SYSTEM
        // Synthetic-CPU write / AMO scratch: distinct from V (0x8000_0000),
        // A (0x9000_0000+), the DDT (0x1_0000) and every page table.
        write64(CPU_WR_ADDR + 0, 0xE000000000000000ULL);
        write64(CPU_WR_ADDR + 8, CPU_WR_INIT1);
        for (uint32_t i = 0; i < 8; ++i)
            write64(CPU_AMO_ADDR + (uint64_t)i * 8, CPU_AMO_INIT + (uint64_t)i);
#endif
    }

    // ---------------------------------------------------------------------
    // memory R-return drive (ordered, head-of-line) -- no Rready hardwire
    // ---------------------------------------------------------------------
#ifndef ACTUAL_DMA_SYSTEM
    void drive_comp() {
        top->comp_aw_ready = 1;
        top->comp_ar_ready = (mem_q.size() < 16) ? 1 : 0;
        top->comp_w_ready  = 1;
        if (!cb_q.empty()) {
            top->comp_b_valid = 1;
            top->comp_b_id    = cb_q.front();
            top->comp_b_resp  = 0;
        } else {
            top->comp_b_valid = 0;
            top->comp_b_id    = 0;
            top->comp_b_resp  = 0;
        }
    }

    void drive_mem_r() {
        top->comp_r_valid = 0;
        top->ddtw_r_valid = 0;
        top->ptw_r_valid  = 0;

        if (mem_q.empty()) return;
        MemRead& h = mem_q.front();
        if (h.latency > 0) { h.latency--; return; }

        switch (h.port) {
        case P_COMP:
            top->comp_r_valid = 1;
            top->comp_r_data  = read64((h.addr & ~uint64_t(7)) + (uint64_t)h.beat * 8);
            top->comp_r_id    = h.id;
            top->comp_r_resp  = 0;
            top->comp_r_last  = (h.beat == h.len) ? 1 : 0;
            break;
        case P_DDTW:
            top->ddtw_r_valid = 1;
            top->ddtw_r_data  = read64((h.addr & ~uint64_t(7)) + (uint64_t)h.beat * 8);
            top->ddtw_r_id    = h.id;
            top->ddtw_r_resp  = 0;
            top->ddtw_r_last  = (h.beat == h.len) ? 1 : 0;
            break;
        case P_PTW:
            top->ptw_r_valid = 1;
            top->ptw_r_data  = read64((h.addr & ~uint64_t(7)) + (uint64_t)h.beat * 8);
            top->ptw_r_id    = h.id;
            top->ptw_r_resp  = 0;
            top->ptw_r_last  = (h.beat == h.len) ? 1 : 0;
            break;
        default: break;
        }
    }
#else
    // ---- SYSTEM mode: ONE shared DDR port (comp + DS merged by the xbar) ----
    // The plain DDR model latency applies uniformly to every accepted DDR read;
    // the real 50/50 DS delayer adds latency on the DS path in RTL only.
    void drive_ddr() {
        ddr_setup_wait = false;
        ddr_model_empty = mem_q.empty();
        top->ddr_aw_ready = 1;
        top->ddr_w_ready  = 1;
        if (write_tail_pause != 0 && !caw_q.empty()) {
            CawEnt& c = caw_q.front();
            if (((c.id >> 4) & 3u) == 2u && c.len == 255 && c.got == 248 && !c.tail_hold_seen) {
                c.tail_hold_seen = true;
                c.tail_release_cycle = g_cycle + write_tail_pause;
                ++write_tail_holds;
                trace_event("ddr_w_tail_hold", c.id, c.addr, write_tail_pause);
            }
            if (c.tail_hold_seen && g_cycle < c.tail_release_cycle) {
                top->ddr_w_ready = 0;
                ++write_tail_hold_cycles;
            }
        }
        top->ddr_ar_ready = (mem_q.size() < 16) ? 1 : 0;
        if (!cb_q.empty()) {
            top->ddr_b_valid = 1;
            top->ddr_b_id    = (uint8_t)cb_q.front();
            top->ddr_b_resp  = 0;
        } else {
            top->ddr_b_valid = 0;
            top->ddr_b_id    = 0;
            top->ddr_b_resp  = 0;
        }

        top->ddr_r_valid = 0;
        if (mem_q.empty()) return;
        // AXI allows R interleaving across different IDs. Promote only the
        // oldest DS request, retaining order within every ID and preserving
        // a VALID payload held from the prior tick. No DUT arbitration changes.
        // Each request retains its original latency/beat state after rotation.
        // The priority WINDOW is the legacy first-V-issue window in the legacy
        // path and the full-era V-completion count in full-batch mode
        // (v_transfers == 64 in the approved full configuration).  The held-R
        // guard applies to BOTH: a beat currently held MUST NOT be displaced.
        const bool ds_window = full_batch
            ? (full_era && full_done_n[0] < (uint32_t)v_transfers)
            : win_open;
        if (ds_priority && !ddr_r_held && ds_window &&
            ((mem_q.front().id >> 4) & 3) != 3) {
            auto ds = std::find_if(mem_q.begin(), mem_q.end(), [](const MemRead& r) {
                return ((r.id >> 4) & 3) == 3;
            });
            if (ds != mem_q.end()) std::rotate(mem_q.begin(), ds, ds + 1);
        }
        MemRead& h = mem_q.front();
        ddr_setup_port = (h.id >> 4) & 3u;
        if (read_latency_overlap && measurement_phase) {
            // Same isolated-request delay as the old model: AR accepted at
            // t first returns at t + latency + 1. Queued requests age from
            // acceptance, allowing their preparation delays to overlap.
            if (g_cycle <= h.accepted_cycle + (long)ptw_latency) {
                ddr_setup_wait = true;
                return;
            }
        } else if (h.latency > 0) {
            --h.latency;
            ddr_setup_wait = true;
            return;
        }

        top->ddr_r_valid = 1;
        top->ddr_r_data  = read64((h.addr & ~uint64_t(7)) + (uint64_t)h.beat * 8);
        top->ddr_r_id    = (uint8_t)h.id;   // 6-bit shared-DDR ID echoed verbatim
        top->ddr_r_resp  = 0;
        top->ddr_r_last  = (h.beat == h.len) ? 1 : 0;
    }
#endif

    void tick() {
        top->nonblock_enable_i  = nonblock_enable  ? 1 : 0;
        top->policy_partition_i = policy_partition ? 1 : 0;
        // Present on BOTH tops: suppress fullbuffer_jobs_i admission
        // permission only while owner_only is requested and the post-warm
        // measurement phase is active.  Buffer size is unchanged.
        top->owner_only_i       = (owner_only && measurement_phase) ? 1 : 0;
#ifdef ACTUAL_DMA_SYSTEM
        // Runtime CPU enable: a real input, not a CpuIssueInterval==0 fake.
        top->cpu_enable_i   = cpu_enable ? 1 : 0;
        top->read_admit_mode_i =
            (read_admit_measure_only && !measurement_phase) ? 1 : read_admit_mode_val;
        top->read_budget_i     = read_budget;
        top->read_period_i     = read_period;
#endif

        top->cfg_sel   = cfg_sel   ? 1 : 0;
        top->cfg_valid = cfg_valid ? 1 : 0;
        top->cfg_write = cfg_write ? 1 : 0;
        top->cfg_addr  = cfg_addr;
        top->cfg_wdata = cfg_wdata;
        top->cfg_wstrb = cfg_wstrb;

        top->clk_i = 0;
#ifdef ACTUAL_DMA_SYSTEM
        drive_ddr();
#else
        drive_comp();
        drive_mem_r();
        top->ddtw_ar_ready = 1;
        top->ptw_ar_ready  = 1;
#endif
        top->eval();
        finite_observe();
        cache_observe();

#ifdef ACTUAL_DMA_SYSTEM
        CHECK(!top->rst_ni || top->dbg_ra_tag_fault == 0,
              "queued read translation tag underflow/overflow");
#endif

        CHECK(!top->rst_ni || top->dbg_e2_fault == 0,
              (std::string("E2 pool fault=") + std::to_string((unsigned)top->dbg_e2_fault) + " cycle=" + std::to_string(g_cycle)).c_str());

        CHECK(!top->rst_ni || top->dbg_e2_mode == 0 || top->dbg_dma_fullbuffer == 0,
              (std::string("E2 mode reported fullbuffer after reset (dbg_e2_fault=") +
               std::to_string((unsigned)top->dbg_e2_fault) + ")").c_str());

        // Modes 4/5 expose the completion-AR metadata queue; its two 8-entry
        // banks bound the accepted-but-not-yet-consumed count at 16.  Modes
        // 0-3 drive these outputs to 0, so this bound is a no-op there.
        // Stateless: no shadow scoreboard, no extra harness counters.
        CHECK(!top->rst_ni || top->dbg_e2_mode < 4 || (uint32_t)top->dbg_e2_queued <= 16,
              "E2 metadata queue exceeded its 16-entry bound");

#ifdef ACTUAL_DMA_SYSTEM
        // ================= read-admission AXI stability (pre-edge) =========
        // A prior held (valid && !ready) must still be VALID next cycle and
        // carry the identical payload, regardless of the current ready.  Only
        // a currently held beat is saved; any other cycle clears the shadow.
        if (ra_up_held_q) {
            CHECK(top->dbg_ra_up_valid,
                  "read-admission upstream AR VALID withdrawn while held");
            CHECK(top->dbg_ra_up_id    == ra_up_id_q &&
                  top->dbg_ra_up_addr  == ra_up_addr_q &&
                  top->dbg_ra_up_len   == ra_up_len_q &&
                  top->dbg_ra_up_attrs == ra_up_attrs_q,
                  "read-admission upstream AR payload changed while held VALID");
        }
        if (top->dbg_ra_up_valid && !top->dbg_ra_up_ready) {
            ra_up_held_q    = true;
            ra_up_id_q      = top->dbg_ra_up_id;
            ra_up_addr_q    = top->dbg_ra_up_addr;
            ra_up_len_q     = top->dbg_ra_up_len;
            ra_up_attrs_q   = top->dbg_ra_up_attrs;
        } else {
            ra_up_held_q = false;
        }

        if (ra_down_held_q) {
            CHECK(top->dbg_ra_down_valid,
                  "read-admission downstream AR VALID withdrawn while held");
            CHECK(top->dbg_ra_down_id    == ra_down_id_q &&
                  top->dbg_ra_down_addr  == ra_down_addr_q &&
                  top->dbg_ra_down_len   == ra_down_len_q &&
                  top->dbg_ra_down_attrs == ra_down_attrs_q,
                  "read-admission downstream AR payload changed while held VALID");
        }
        if (top->dbg_ra_down_valid && !top->dbg_ra_down_ready) {
            ra_down_held_q    = true;
            ra_down_id_q      = top->dbg_ra_down_id;
            ra_down_addr_q    = top->dbg_ra_down_addr;
            ra_down_len_q     = top->dbg_ra_down_len;
            ra_down_attrs_q   = top->dbg_ra_down_attrs;
        } else {
            ra_down_held_q = false;
        }

        if (top->dbg_ra_new_captured) ++n_ra_captured;
        if (top->dbg_ra_ar_fire)      ++n_ra_ar_fire;
#endif

        // ================= pre-edge snapshot ==============================
        bool any_fire = false;

#ifdef ACTUAL_DMA_SYSTEM
        const bool     f_ddr_ar   = top->ddr_ar_valid && top->ddr_ar_ready;
        const bool     f_ddr_aw   = top->ddr_aw_valid && top->ddr_aw_ready;
        const bool     f_ddr_w    = top->ddr_w_valid  && top->ddr_w_ready;
        const bool     f_ddr_b    = top->ddr_b_valid  && top->ddr_b_ready;
        const bool     f_ddr_r    = top->ddr_r_valid  && top->ddr_r_ready;
        const bool     s_ddr_r_held = top->ddr_r_valid && !top->ddr_r_ready;
        const uint64_t s_ddr_ar_a = top->ddr_ar_addr;
        const uint32_t s_ddr_ar_l = (uint32_t)top->ddr_ar_len;
        const uint32_t s_ddr_ar_i = (uint32_t)top->ddr_ar_id;
        const uint64_t s_ddr_aw_a = top->ddr_aw_addr;
        const uint32_t s_ddr_aw_l = (uint32_t)top->ddr_aw_len;
        const uint32_t s_ddr_aw_i = (uint32_t)top->ddr_aw_id;
        const uint64_t s_ddr_w_d  = top->ddr_w_data;
        const uint8_t  s_ddr_w_s  = (uint8_t)top->ddr_w_strb;
        const bool     s_ddr_w_l  = top->ddr_w_last;
        any_fire = f_ddr_ar || f_ddr_aw || f_ddr_w || f_ddr_b || f_ddr_r;
#else
        const bool     s_comp_ar_v = top->comp_ar_valid;
        const bool     s_comp_ar_r = top->comp_ar_ready;
        const uint32_t s_comp_ar_i = top->comp_ar_id;
        const uint64_t s_comp_ar_a = top->comp_ar_addr;
        const uint32_t s_comp_ar_l = (uint32_t)top->comp_ar_len;

        const bool     s_ddtw_ar_v = top->ddtw_ar_valid;
        const bool     s_ddtw_ar_r = top->ddtw_ar_ready;
        const uint64_t s_ddtw_ar_a = top->ddtw_ar_addr;
        const uint32_t s_ddtw_ar_l = (uint32_t)top->ddtw_ar_len;
        const uint32_t s_ddtw_ar_i = (uint32_t)top->ddtw_ar_id;

        const bool     s_ptw_ar_v = top->ptw_ar_valid;
        const bool     s_ptw_ar_r = top->ptw_ar_ready;
        const uint64_t s_ptw_ar_a = top->ptw_ar_addr;
        const uint32_t s_ptw_ar_l = (uint32_t)top->ptw_ar_len;
        const uint32_t s_ptw_ar_i = (uint32_t)top->ptw_ar_id;

        const bool     s_comp_aw_v = top->comp_aw_valid;
        const bool     s_comp_aw_r = top->comp_aw_ready;
        const uint32_t s_comp_aw_i = top->comp_aw_id;
        const uint64_t s_comp_aw_a = top->comp_aw_addr;
        const uint32_t s_comp_aw_l = (uint32_t)top->comp_aw_len;

        const bool     s_comp_w_v = top->comp_w_valid;
        const bool     s_comp_w_r = top->comp_w_ready;
        const uint64_t s_comp_w_d = top->comp_w_data;
        const uint8_t  s_comp_w_s = (uint8_t)top->comp_w_strb;
        const bool     s_comp_w_l = top->comp_w_last;

        const bool     s_comp_b_v = top->comp_b_valid;
        const bool     s_comp_b_r = top->comp_b_ready;

        const bool     s_comp_r_v = top->comp_r_valid;
        const bool     s_comp_r_r = top->comp_r_ready;
        const bool     s_ddtw_r_v = top->ddtw_r_valid;
        const bool     s_ddtw_r_r = top->ddtw_r_ready;
        const bool     s_ptw_r_v  = top->ptw_r_valid;
        const bool     s_ptw_r_r  = top->ptw_r_ready;

        const bool f_comp_ar = s_comp_ar_v && s_comp_ar_r;
        const bool f_ddtw_ar = s_ddtw_ar_v && s_ddtw_ar_r;
        const bool f_ptw_ar  = s_ptw_ar_v  && s_ptw_ar_r;
        const bool f_comp_aw = s_comp_aw_v && s_comp_aw_r;
        const bool f_comp_w  = s_comp_w_v  && s_comp_w_r;
        const bool f_comp_b  = s_comp_b_v  && s_comp_b_r;
        const bool f_comp_r  = s_comp_r_v  && s_comp_r_r;
        const bool f_ddtw_r  = s_ddtw_r_v  && s_ddtw_r_r;
        const bool f_ptw_r   = s_ptw_r_v   && s_ptw_r_r;

        any_fire = f_comp_ar || f_ddtw_ar || f_ptw_ar || f_comp_aw || f_comp_w ||
                   f_comp_b  || f_comp_r  || f_ddtw_r  || f_ptw_r;
#endif

        if (any_fire) last_progress_cycle = g_cycle;

        // V (DMA0 = bank0) independent completion progress.
        if (top->dbg_dma_done & 1) v_progress_cycle = g_cycle;
        // Warm-phase hardware overlap scoreboard.  Only active during warm
        // (and its drain); uses the real per-channel issue/done observer
        // pulses, so the overlap counter is a cycle count of genuinely
        // unfinished jobs, NOT a software-inflight approximation.
        if (warm_hw_track) {
            const uint32_t iss = (uint32_t)top->dbg_dma_issue & 3u;
            const uint32_t dnn = (uint32_t)top->dbg_dma_done  & 3u;
            // Process done before issue so a back-to-back
            // done-then-issue cycle keeps the channel busy.
            if (dnn & 1u) { ++warm_hw_v_done; warm_hw_v_busy = false; }
            if (iss & 1u) { ++warm_hw_v_issue; warm_hw_v_busy = true; }
            if (dnn & 2u) { ++warm_hw_a_done; warm_hw_a_busy = false; }
            if (iss & 2u) { ++warm_hw_a_issue; warm_hw_a_busy = true; }
            if (warm_hw_v_busy && warm_hw_a_busy) ++warm_overlap_ticks;
        }

        if (top->dbg_fast_resp_valid && top->dbg_fast_resp_ready) {
            ++n_fast;
            ++n_fast_bank[top->dbg_fast_resp_bank & 1];
        }
        if (top->dbg_tl_req_valid && top->dbg_tl_req_ready) {
            ++n_tl_accept;
            ++n_req_bank[top->dbg_tl_req_bank & 1];
        }
        if (top->dbg_tl_resp_valid && top->dbg_tl_resp_ready) {
            ++n_tl_resp;
            ++n_resp_bank[top->dbg_tl_resp_bank & 1];
        }
        if (top->dbg_tl_ptw_active) ++n_ptw_active;
        if (top->dbg_tl_iotlb_lookup) {
            ++n_iotlb_lookup;
            if (top->dbg_tl_iotlb_hit) ++n_iotlb_hit;
        }

#ifdef ACTUAL_DMA_SYSTEM
        // ---- full-batch per-copy recording + raw era counters -----------
        // All values are PRE-EDGE samples.  DONE is processed before ISSUE so
        // a back-to-back same-cycle done->issue keeps ready[j] == done[j-1].
        if (full_era) {
            const uint32_t fi = (uint32_t)top->dbg_dma_issue & 3u;
            const uint32_t fd = (uint32_t)top->dbg_dma_done  & 3u;
            for (int c = 0; c < 2; ++c) {
                const uint32_t bit    = 1u << c;
                const uint32_t target = (c == 0) ? v_transfers : (uint32_t)a_target;
                // DONE is processed BEFORE ISSUE so a back-to-back same-cycle
                // done->issue keeps ready[j] == done[j-1].
                if (fd & bit) {
                    // Every pulse counts.  An extra pulse is a HARD failure:
                    // saturation would silently hide a duplicate DONE.
                    CHECK(full_done_n[c] < target,
                          "full-batch DONE pulse beyond the channel target");
                    CHECK(full_done_n[c] < full_issue_n[c],
                          "full-batch DONE pulse without a matching ISSUE");
                    full_done_cyc[c].push_back(g_cycle);
                    ++full_done_n[c];
                    full_final_done[c]      = g_cycle;
                    full_last_progress[c]   = g_cycle;
                }
                if (fi & bit) {
                    CHECK(full_issue_n[c] < target,
                          "full-batch ISSUE pulse beyond the channel target");
                    // Strict single-active: no new job may start while the
                    // previous job of the same channel is still outstanding.
                    CHECK(full_issue_n[c] == full_done_n[c],
                          "full-batch channel issued a second job before DONE");
                    const long ready = (full_issue_n[c] == 0)
                        ? full_t0
                        : full_done_cyc[c].back();
                    CHECK(ready <= g_cycle,
                          "full-batch per-copy ready time is after its issue");
                    full_ready_cyc[c].push_back(ready);
                    full_issue_cyc[c].push_back(g_cycle);
                    ++full_issue_n[c];
                    if (!full_issue_seen[c]) {
                        full_issue_seen[c]  = true;
                        full_first_issue[c] = g_cycle;
                    }
                    full_last_progress[c] = g_cycle;
                }
            }
            if (top->dbg_tl_req_valid && top->dbg_tl_req_ready) ++full_tl_accept;
            if (top->dbg_tl_resp_valid && top->dbg_tl_resp_ready) ++full_tl_resp;
            if (top->dbg_tl_ptw_active) ++full_ptw_active;
            if (top->dbg_tl_ptw_r_fire) ++full_ptw_r_fire;
            if (top->dbg_tl_iotlb_lookup) {
                ++full_iotlb_lookup;
                if (top->dbg_tl_iotlb_hit) ++full_iotlb_hit;
            }
            if (top->dbg_fast_resp_valid && top->dbg_fast_resp_ready) ++full_fast;
            if (top->dbg_comp_ar_fire) ++full_comp_ar;
            if (top->dbg_comp_aw_fire) ++full_comp_aw;
            if (top->dbg_comp_w_fire)  ++full_comp_w;
            if (top->dbg_ddtw_ar_fire) ++full_ddtw_ar;
            if (top->dbg_ptw_ar_fire)  ++full_ptw_ar;
        }

        // ---- full-batch trace (independent of win_open) ----------------
        // Event-driven only: real hardware issue/done pulses plus the existing
        // payload / PTW / DDR diagnostics over the WHOLE t0..quiet era, so the
        // full path is visible even when no legacy measurement window is open.
        if (full_era && event_trace) {
            const uint32_t fissue = (uint32_t)top->dbg_dma_issue & 3u;
            const uint32_t fdone  = (uint32_t)top->dbg_dma_done  & 3u;
            if (fissue)
                std::fprintf(event_trace, "%ld,full_dma_issue,%u,0,0\n",
                             g_cycle - full_t0, fissue);
            if (fdone)
                std::fprintf(event_trace, "%ld,full_dma_done,%u,0,0\n",
                             g_cycle - full_t0, fdone);
            if (f_ddr_ar)
                std::fprintf(event_trace, "%ld,full_ddr_ar,%u,%llu,%u\n",
                             g_cycle - full_t0, s_ddr_ar_i,
                             (unsigned long long)s_ddr_ar_a, s_ddr_ar_l);
            if (f_ddr_aw)
                std::fprintf(event_trace, "%ld,full_ddr_aw,%u,%llu,%u\n",
                             g_cycle - full_t0, s_ddr_aw_i,
                             (unsigned long long)s_ddr_aw_a, s_ddr_aw_l);
            if (f_ddr_w)
                std::fprintf(event_trace, "%ld,full_ddr_w,%u,%llu,%u\n",
                             g_cycle - full_t0, (unsigned)s_ddr_w_l,
                             (unsigned long long)s_ddr_w_d, (unsigned)s_ddr_w_s);
            if (f_ddr_b)
                std::fprintf(event_trace, "%ld,full_ddr_b,%u,0,0\n",
                             g_cycle - full_t0, (unsigned)top->ddr_b_id);
            if (f_ddr_r && !mem_q.empty()) {
                const MemRead& r = mem_q.front();
                std::fprintf(event_trace, "%ld,full_ddr_r,%u,%llu,%u\n",
                             g_cycle - full_t0, (unsigned)r.id,
                             (unsigned long long)r.addr, (unsigned)r.beat);
            }
            if (top->dbg_tl_ptw_active != full_trace_ptw_active) {
                std::fprintf(event_trace, "%ld,full_ptw_%s,%u,0,0\n",
                             g_cycle - full_t0,
                             top->dbg_tl_ptw_active ? "start" : "end",
                             (unsigned)top->dbg_main_bank);
                full_trace_ptw_active = top->dbg_tl_ptw_active;
            }
            if (top->dbg_iotlb_fill)
                std::fprintf(event_trace, "%ld,full_fill,%u,0,0\n",
                             g_cycle - full_t0, (unsigned)top->dbg_main_bank);
            if (top->dbg_ptw_ar_fire)
                std::fprintf(event_trace, "%ld,full_ptw_ar,%u,0,0\n",
                             g_cycle - full_t0, (unsigned)top->dbg_main_bank);
            if (top->dbg_tl_ptw_r_fire)
                std::fprintf(event_trace, "%ld,full_ptw_r,%u,0,0\n",
                             g_cycle - full_t0, (unsigned)top->dbg_main_bank);
            if (top->dbg_fast_resp_valid && top->dbg_fast_resp_ready)
                std::fprintf(event_trace, "%ld,full_fast,%u,0,0\n",
                             g_cycle - full_t0, (unsigned)top->dbg_fast_resp_bank);
        }
#endif

        // ================= measurement window (pre-edge) ==================
        // Gated by win_open; see the counter block in class Tb.  Nothing is
        // counted during warm-up, the A drain, drain-to-quiet or the byte
        // verification, because win_open is false there.
        // Track actual job occupancy from before the trigger sequence. This
        // includes A's first issue even when it precedes the window opening.
        const uint32_t measure_issue = (uint32_t)top->dbg_dma_issue & 3u;
        const uint32_t measure_done = (uint32_t)top->dbg_dma_done & 3u;
        const bool opening = win_armed && !win_seen && (measure_issue & 1u);
        if (opening) {
            win_open = true;
            win_seen = true;
            win_open_cycle = g_cycle;
        }
        if (win_open && !opening) {
            ++w_cycles;

#ifdef ACTUAL_DMA_SYSTEM
            // Mutually exclusive service states at the existing PRE-EDGE
            // measurement sample. This observes the memory model only.
            if (ddr_model_empty) ++w_read_empty;
            else if (ddr_setup_wait) {
                ++w_read_setup;
                ++w_read_setup_port[ddr_setup_port];
            } else if (top->ddr_r_valid && top->ddr_r_ready) ++w_read_transfer;
            else if (top->ddr_r_valid) ++w_read_backpressure;
            else CHECK(false, "DDR read service state is unclassified");
            // Read-admission proxy: accumulate the PRE-EDGE event pulses
            // directly.  No open/close cumulative differences are used.
            if (top->dbg_ra_new_captured)      ++w_ra_captures;
            if (top->dbg_ra_first_offer)       ++w_ra_firstoffers;
            if (top->dbg_ra_ar_fire)           ++w_ra_offer_handshakes;
            if (top->dbg_ra_capture_fast)      ++w_ra_fastread;
            if (top->dbg_ra_gate_ingress)      ++w_ra_ingress;
            if (top->dbg_ra_gate_budget)       ++w_ra_budget;
            if (top->dbg_ra_exempt)            ++w_ra_exempt;
            if (top->dbg_ra_oversize_escape)   ++w_ra_oversize;
            if (top->dbg_ra_fastgated)         ++w_ra_fastgated;
            if (top->dbg_ra_phase_reset)       ++w_ra_phase_resets;
            w_ra_gate = w_ra_ingress + w_ra_budget;
#endif

            const uint32_t w_dnn = (uint32_t)top->dbg_dma_done  & 3u;
            if (w_dnn & 1u) ++w_v_done;
            if (w_dnn & 2u) ++w_a_done;
            if (w_v_busy && w_a_busy) ++w_both_pending;

            if (top->dbg_tl_req_valid && top->dbg_tl_req_ready) {
                ++w_tl_accept;
                ++w_req_bank[top->dbg_tl_req_bank & 1];
            }
            if (top->dbg_tl_resp_valid && top->dbg_tl_resp_ready) {
                ++w_tl_resp;
                ++w_resp_bank[top->dbg_tl_resp_bank & 1];
            }
            if (top->dbg_fast_resp_valid && top->dbg_fast_resp_ready) {
                ++w_fast;
                ++w_fast_bank[top->dbg_fast_resp_bank & 1];
            }
            if (top->dbg_tl_iotlb_lookup) {
                ++w_iotlb_lookup;
                if (top->dbg_tl_iotlb_hit) ++w_iotlb_hit;
            }
            // ptw_active is a LEVEL (counted per cycle, like the existing
            // whole-scenario counter); ptw_r_fire is a pulse.
            if (top->dbg_tl_ptw_active) ++w_ptw_active;
            if (top->dbg_tl_ptw_r_fire) ++w_ptw_r_fire;
#ifdef ACTUAL_DMA_SYSTEM
            if (top->dbg_tl_ptw_active != trace_ptw_active)
                trace_event(top->dbg_tl_ptw_active ? "ptw_start" : "ptw_end",
                            top->dbg_main_bank, 0, 0);
            trace_ptw_active = top->dbg_tl_ptw_active;
            unsigned aw_flags = top->dbg_tr_aw_stall ? (top->dbg_aw_wait_flags | 16u) : 0;
            if (aw_flags != trace_aw_flags)
                trace_event("aw_wait_change", top->dbg_tr_aw_bank, 0, aw_flags);
            trace_aw_flags = aw_flags;
            if (w_dnn) trace_event("dma_done", w_dnn, 0, w_v_done);
            if (top->dbg_fast_resp_valid && top->dbg_fast_resp_ready)
                trace_event("fast_response", top->dbg_fast_resp_bank, 0, 0);
            if (top->dbg_iotlb_fill) trace_event("fill", top->dbg_main_bank, 0, 0);
            if (top->dbg_ptw_ar_fire) trace_event("ptw_ar", top->dbg_main_bank, 0, 0);
            if (top->dbg_tl_ptw_r_fire) trace_event("ptw_r", top->dbg_main_bank, 0, 0);
            if (top->dbg_ra_new_captured) {
                unsigned cap_tag = (unsigned)top->dbg_ra_up_id |
                                   ((unsigned)top->dbg_ra_up_bank << 4) |
                                   ((unsigned)top->dbg_ra_capture_fast << 5);
                trace_event("newcaptured", cap_tag, top->dbg_ra_up_addr,
                            top->dbg_ra_up_len);
            }
            if (top->dbg_ra_first_offer)
                trace_event("firstoffer", top->dbg_ra_down_id,
                            top->dbg_ra_down_addr, top->dbg_ra_down_len);
            if (top->dbg_ra_ar_fire)
                trace_event("arfire", top->dbg_ra_down_id,
                            top->dbg_ra_down_addr, top->dbg_ra_down_len);
            if (top->dbg_ra_gate_ingress)
                trace_event("gate_ingress", top->dbg_ra_down_id,
                            top->dbg_ra_down_addr, top->dbg_ra_down_len);
            if (top->dbg_ra_gate_budget)
                trace_event("gate_budget", top->dbg_ra_down_id,
                            top->dbg_ra_down_addr, top->dbg_ra_down_len);
            if (top->dbg_ra_exempt)
                trace_event("exempt", top->dbg_ra_down_id,
                            top->dbg_ra_down_addr, top->dbg_ra_down_len);
            if (top->dbg_ra_oversize_escape)
                trace_event("oversize", top->dbg_ra_down_id,
                            top->dbg_ra_down_addr, top->dbg_ra_down_len);
            if (top->dbg_ra_fastgated)
                trace_event("fastgated", top->dbg_ra_down_id,
                            top->dbg_ra_down_addr, top->dbg_ra_down_len);
            if (top->dbg_ra_phase_reset)
                trace_event("phase_reset", top->dbg_ra_up_bank, 0, 0);
            if (f_ddr_ar) trace_event("ddr_ar", s_ddr_ar_i, s_ddr_ar_a, s_ddr_ar_l);
            if (f_ddr_aw) trace_event("ddr_aw", s_ddr_aw_i, s_ddr_aw_a, s_ddr_aw_l);
            if (f_ddr_r && mem_q.front().beat == 0)
                trace_event("ddr_r_first", mem_q.front().id, mem_q.front().addr,
                            g_cycle - mem_q.front().accepted_cycle);
            if (f_ddr_r && top->ddr_r_last) {
                const MemRead& r = mem_q.front();
                trace_event("ddr_r_last", r.id, r.addr, g_cycle - r.accepted_cycle);
                if (((r.id >> 4) & 3) == 3 && r.accepted_cycle > win_open_cycle) {
                    uint64_t latency = g_cycle - r.accepted_cycle;
                    ++w_ds_latency_n;
                    w_ds_latency_sum += latency;
                    w_ds_latency_max = std::max(w_ds_latency_max, latency);
                }
            }
            // Shared DDR port.  f_ddr_* are this tick's PRE-EDGE fire flags;
            // the stall counters use the PRE-EDGE valid/ready sample.
            // NOTE: drive_ddr() drives ddr_aw_ready / ddr_w_ready to 1
            // permanently, so w_ddr_aw_stall / w_ddr_w_stall are structurally
            // 0 in this model.  They must NOT be read as "the board never
            // backpressures shared AW": this DDR model has no AW backpressure
            // at all.
            if (f_ddr_ar) { ++w_ddr_ar; ++w_ddr_ar_slv[(s_ddr_ar_i >> 4) & 3]; }
            if (f_ddr_aw) {
                ++w_ddr_aw;
                ++w_ddr_aw_slv[(s_ddr_aw_i >> 4) & 3];
                // Destination region: the A ring lives at A_SRC_PA_BASE
                // (0x9000_0000+) and V at V_SRC_PA (0x8000_0000+); everything
                // below the synthetic CPU scratch (0x8100_0000) is V.
                if (s_ddr_aw_a >= A_SRC_PA_BASE)      ++w_ddr_aw_a;
                else if (s_ddr_aw_a >= V_SRC_PA &&
                         s_ddr_aw_a <  CPU_WR_ADDR)   ++w_ddr_aw_v;
            }
            if (f_ddr_w) ++w_ddr_w;
            if (f_ddr_r) ++w_ddr_r;
            if (f_ddr_b) ++w_ddr_b;
            if (top->ddr_ar_valid && !top->ddr_ar_ready) ++w_ddr_ar_stall;
            if (top->ddr_r_valid  && !top->ddr_r_ready)  ++w_ddr_r_stall;
            if (top->ddr_aw_valid && !top->ddr_aw_ready) ++w_ddr_aw_stall;
            if (top->ddr_w_valid  && !top->ddr_w_ready)  ++w_ddr_w_stall;
            if (top->dbg_comp_ar_fire) ++w_comp_ar_fire;
            if (top->dbg_comp_aw_fire) ++w_comp_aw_fire;
            if (top->dbg_comp_w_fire)  ++w_comp_w_fire;
            if (top->dbg_ddtw_ar_fire) ++w_ddtw_ar_fire;
            if (top->dbg_ptw_ar_fire)  ++w_ptw_ar_fire;
            if (top->dbg_ds_ar_valid && !top->dbg_ds_ar_ready) ++w_ds_ar_stall;
            if (top->dbg_ds_r_valid  && !top->dbg_ds_r_ready)  ++w_ds_r_stall;
            if (top->dbg_tr_aw_stall) {
                ++w_ingress_aw_stall[top->dbg_tr_aw_bank & 1];
                unsigned flags = top->dbg_aw_wait_flags;
                unsigned cls = 4;
                for (unsigned i = 0; i < 4; ++i) {
                    if (flags & (1u << i)) { ++w_aw_raw[i]; if (cls == 4) cls = i; }
                }
                ++w_aw_class[cls];
            }
            if (top->dbg_iotlb_fill) ++w_fill[top->dbg_main_bank & 1];
            if (top->dbg_tl_ptw_active) ++w_ptw_bank_cycles[top->dbg_main_bank & 1];
            if (!mem_q.empty() && ((mem_q.front().id >> 4) & 3) == 2) {
                for (const auto& r : mem_q) {
                    if (((r.id >> 4) & 3) == 3) { ++w_ds_behind_comp_cycles; break; }
                }
            }
#endif
            if (w_v_done == v_transfers) {
                win_open = false;
                win_armed = false;
                win_close_cycle = g_cycle;
            }
        }
        if (win_armed || opening || win_close_cycle == g_cycle) {
            if (measure_done & 1u) w_v_busy = false;
            if (measure_issue & 1u) w_v_busy = true;
            if (measure_done & 2u) w_a_busy = false;
            if (measure_issue & 2u) w_a_busy = true;
        }

#ifdef ACTUAL_DMA_SYSTEM
        // Underlying walker counters: the real ds_if merge hides the external
        // dd/ptw ports, so walk evidence comes from the harness taps.
        if (top->dbg_ddtw_ar_fire) ++n_walk_ddtw;
        if (top->dbg_ptw_ar_fire)  ++n_walk_ptw;
        // Synthetic-CPU independent progress.
        if (top->dbg_cpu_issued != last_cpu_issued ||
            top->dbg_cpu_completed != last_cpu_completed) {
            cpu_progress_cycle = g_cycle;
            last_cpu_issued    = top->dbg_cpu_issued;
            last_cpu_completed = top->dbg_cpu_completed;
        }
        // Synthetic-CPU write / AMO independent progress.  Refreshed ONLY by
        // the new write/AMO lifecycle taps, so a stalled write path cannot be
        // hidden by read progress.
        if (top->dbg_cpu_wr_issued != last_cpu_wr_issued ||
            top->dbg_cpu_wr_completed != last_cpu_wr_completed ||
            top->dbg_cpu_amo_issued != last_cpu_amo_issued ||
            top->dbg_cpu_amo_completed != last_cpu_amo_completed) {
            cpu_wr_progress_cycle  = g_cycle;
            last_cpu_wr_issued     = top->dbg_cpu_wr_issued;
            last_cpu_wr_completed  = top->dbg_cpu_wr_completed;
            last_cpu_amo_issued    = top->dbg_cpu_amo_issued;
            last_cpu_amo_completed = top->dbg_cpu_amo_completed;
        }
        // AMO old-value accumulation continuity scoreboard.
        if (top->dbg_cpu_amo_r_fire) {
            CHECK(top->dbg_cpu_amo_r_data == cpu_amo_expected,
                  "AMO returned old value broke accumulation continuity");
            cpu_amo_expected += CPU_AMO_ADD;
            ++n_cpu_amo_obs;
        }
#endif

        // ================= rising edge ====================================
        top->clk_i = 1;
        top->eval();
        if (opening) {
            fg_raw_open = (uint32_t)top->dbg_frontier_grant;
            fw_raw_open = (uint32_t)top->dbg_frontier_wait;
        }
        if (win_seen && !win_open && win_close_cycle == g_cycle) {
            fg_raw_close = (uint32_t)top->dbg_frontier_grant;
            fw_raw_close = (uint32_t)top->dbg_frontier_wait;
        }

#ifdef ACTUAL_DMA_SYSTEM
        ddr_r_held = s_ddr_r_held;
        if (f_ddr_ar) {
            ++n_ddr_ar;
            ++n_slv_ar[(s_ddr_ar_i >> 4) & 3];
            // full-batch: real payload read bytes for the completion master
            // (slave port 2).  DS walk (3) and CPU (0) are excluded.
            if (full_era && (((s_ddr_ar_i >> 4) & 3u) == 2u)) {
                const unsigned ch = (unsigned)((s_ddr_ar_i >> 2) & 1u);
                ++full_ar_n[ch];
                full_rd_bytes[ch] += ((uint64_t)s_ddr_ar_l + 1ULL) * 8ULL;
            }
            MemRead r; r.port = P_DDR; r.addr = s_ddr_ar_a;
            r.len = (uint8_t)s_ddr_ar_l; r.id = (uint8_t)s_ddr_ar_i;
            r.beat = 0; r.latency = (int)ptw_latency;
            r.accepted_cycle = g_cycle;
            mem_q.push_back(r);
        }
        if (f_ddr_aw) {
            ++n_ddr_aw;
            if (full_era) {
                const unsigned slv = (s_ddr_aw_i >> 4) & 3u;
                const unsigned chn = (unsigned)((s_ddr_aw_i >> 2) & 1u);
                if (slv == 2u) {
                    // Completion write payload.  Classification needs BOTH the
                    // completion slave port / bank bit AND a legal 4 KiB
                    // physical payload window (the V measurement destination
                    // page or an A ring destination page).  A synthetic-CPU
                    // write to the SAME V address arrives on slave port 0 and
                    // is therefore excluded.
                    const uint64_t a0 = s_ddr_aw_a;
                    const uint64_t a1 = a0 + ((uint64_t)s_ddr_aw_l + 1ULL) * 8ULL - 1ULL;
                    CHECK((a0 >> 12) == (a1 >> 12),
                          "full-batch AW payload crosses a 4 KiB page");
                    const bool in_v = (a0 >= v_measure_dst_pa() && a1 < v_measure_dst_pa() + PAGE_BYTES);
                    const bool in_a = (a0 >= A_DST_PA_BASE &&
                                       a1 <  A_DST_PA_BASE + (uint64_t)a_pages * 0x1000ULL);
                    CHECK(chn == 0 ? in_v : in_a,
                          "full-batch AW payload outside its channel destination map");
                    ++full_aw_n[chn];
                }
            }
            CawEnt c; c.id = s_ddr_aw_i; c.addr = s_ddr_aw_a;
            c.len = (uint8_t)s_ddr_aw_l; c.got = 0;
            caw_q.push_back(c);
        }
        if (f_ddr_w) {
            CHECK(!caw_q.empty(), "completion W without a pending completion AW");
            CawEnt& c = caw_q.front();
            CHECK(c.got < (uint32_t)c.len + 1, "too many completion W beats");
            // full-batch: strobe-weighted write payload bytes, attributed by
            // the pending AW id (slave port 2 only).
            if (full_era && (((c.id >> 4) & 3u) == 2u)) {
                const unsigned ch = (unsigned)((c.id >> 2) & 1u);
                unsigned bits = 0;
                for (int i = 0; i < 8; ++i)
                    if (s_ddr_w_s & (uint8_t)(1u << i)) ++bits;
                full_wr_bytes[ch] += bits;
            }
            write_beat((c.addr & ~uint64_t(7)) + (uint64_t)c.got * 8, s_ddr_w_d, s_ddr_w_s);
            c.got++;
            if (s_ddr_w_l) {
                CHECK(c.got == (uint32_t)c.len + 1, "completion W burst length mismatch");
                cb_q.push_back(c.id);
                caw_q.pop_front();
            }
        }
        if (f_ddr_b) {
            ++n_ddr_b;
            CHECK(!cb_q.empty(), "completion B handshake with empty cb_q");
            const uint32_t bq_id = (uint32_t)(uint8_t)cb_q.front();
            // The driven B must echo the queued completion AW id.
            CHECK((uint32_t)top->ddr_b_id == bq_id,
                  "DDR B id does not match the queued completion AW id");
            // full-batch: B response conservation (slave port 2 only).
            if (full_era && ((bq_id >> 4) & 3u) == 2u) {
                const unsigned chn = (unsigned)((bq_id >> 2) & 1u);
                ++full_b_n[chn];
                if (top->ddr_b_resp != 0) ++full_err[chn];
            }
            cb_q.pop_front();
        }
        if (f_ddr_r) {
            ++n_ddr_r;
            CHECK(!mem_q.empty(), "R handshake with an empty DDR read queue");
            MemRead& h = mem_q.front();
            CHECK(h.port == P_DDR, "R handshake on an unexpected port");
            // The R payload driven this cycle must match the queue head: the
            // id is echoed verbatim and LAST marks the burst tail.
            CHECK((uint32_t)top->ddr_r_id == (uint32_t)h.id &&
                  ((h.beat == h.len) == (top->ddr_r_last != 0)),
                  "DDR R id/LAST does not match the queued request head");
            // full-batch: accepted-AR -> R byte conservation (slave port 2).
            if (full_era && ((((uint8_t)h.id) >> 4) & 3u) == 2u) {
                const unsigned chn = (unsigned)((((uint8_t)h.id) >> 2) & 1u);
                // Payload range: only the completion source pages may count.
                const uint64_t a1 = h.addr + ((uint64_t)h.len + 1ULL) * 8ULL - 1ULL;
                CHECK((h.addr >> 12) == (a1 >> 12),
                      "full-batch AR payload crosses a 4 KiB page");
                const bool in_v = (h.addr >= V_SRC_PA &&
                                   a1 <  V_SRC_PA + (uint64_t)PAGE_BYTES);
                const bool in_a = (h.addr >= A_SRC_PA_BASE &&
                                   a1 <  A_SRC_PA_BASE + (uint64_t)a_pages * 0x1000ULL);
                CHECK(chn == 0 ? in_v : in_a,
                      "full-batch AR payload outside its channel source map");
                ++full_r_n[chn];
                full_r_return_bytes[chn] += 8ULL;   // one 64-bit R beat
                if (top->ddr_r_resp != 0) ++full_err[chn];
            }
            if (h.beat == h.len) mem_q.pop_front();
            else                 h.beat++;
        }
#else
        if (f_comp_ar) {
            ++n_comp_ar;
            MemRead r; r.port = P_COMP; r.addr = s_comp_ar_a;
            r.len = (uint8_t)s_comp_ar_l; r.id = (uint8_t)s_comp_ar_i;
            r.beat = 0; r.latency = 1;
            mem_q.push_back(r);
        }
        if (f_ddtw_ar) {
            ++n_ddtw_ar;
            MemRead r; r.port = P_DDTW; r.addr = s_ddtw_ar_a;
            r.len = (uint8_t)s_ddtw_ar_l; r.id = (uint8_t)s_ddtw_ar_i;
            r.beat = 0; r.latency = 1;
            mem_q.push_back(r);
        }
        if (f_ptw_ar) {
            ++n_ptw_ar;
            MemRead r; r.port = P_PTW; r.addr = s_ptw_ar_a;
            r.len = (uint8_t)s_ptw_ar_l; r.id = (uint8_t)s_ptw_ar_i;
            r.beat = 0; r.latency = (int)ptw_latency;
            mem_q.push_back(r);
        }
        if (f_comp_aw) {
            CawEnt c; c.id = s_comp_aw_i; c.addr = s_comp_aw_a;
            c.len = (uint8_t)s_comp_aw_l; c.got = 0;
            caw_q.push_back(c);
        }
        if (f_comp_w) {
            CHECK(!caw_q.empty(), "completion W without a pending completion AW");
            CawEnt& c = caw_q.front();
            CHECK(c.got < (uint32_t)c.len + 1, "too many completion W beats");
            write_beat((c.addr & ~uint64_t(7)) + (uint64_t)c.got * 8, s_comp_w_d, s_comp_w_s);
            c.got++;
            if (s_comp_w_l) {
                CHECK(c.got == (uint32_t)c.len + 1, "completion W burst length mismatch");
                cb_q.push_back(c.id);
                caw_q.pop_front();
            }
        }
        if (f_comp_b) {
            CHECK(!cb_q.empty(), "completion B handshake with empty cb_q");
            cb_q.pop_front();
        }
        if (f_comp_r || f_ddtw_r || f_ptw_r) {
            MemRead& h = mem_q.front();
            CHECK(h.port == (f_comp_r ? P_COMP : (f_ddtw_r ? P_DDTW : P_PTW)),
                  "R handshake on an unexpected port");
            if (h.beat == h.len) mem_q.pop_front();
            else                 h.beat++;
        }
#endif

        top->clk_i = 0;
        top->eval();
        ++g_cycle;
    }

    // ---------------------------------------------------------------------
    // configuration transactions (blocking; interleaved with tick())
    // ---------------------------------------------------------------------
    uint64_t cfg_xact(bool sel, bool write, uint64_t addr, uint64_t wdata, uint8_t wstrb) {
        finite_event("mmio_begin", int(sel), finite_cfg_span, addr, write, 0, wdata);
        cfg_sel = sel; cfg_write = write; cfg_addr = addr;
        cfg_wdata = wdata; cfg_wstrb = wstrb; cfg_valid = true;

        long t = 0;
        for (; t < CFG_TIMEOUT; ++t) {
            tick();
            if (top->cfg_ready) break;
        }
        if (!top->cfg_ready) {
            cfg_valid = false;
            dump_stall("cfg-timeout");
            throw TestFailure("configuration transaction never completed");
        }
        uint64_t rd = top->cfg_rdata;
        finite_event("mmio_ack", int(sel), finite_cfg_span, addr, write, top->cfg_error, write ? wdata : rd);
        bool     er = top->cfg_error;
        cfg_valid = false;
        tick();                      // let the SV FSM return to IDLE
        if (er) fail("configuration transaction returned an error", __FILE__, __LINE__);
        finite_event("mmio_return", int(sel), finite_cfg_span, addr, write, 0, write ? wdata : rd);
        return rd;
    }

    void cfg_wr(bool sel, uint64_t addr, uint64_t data) {
        cfg_xact(sel, true, addr, data, 0xFF);
    }
    uint64_t cfg_rd(bool sel, uint64_t addr) {
        return cfg_xact(sel, false, addr, 0, 0x00);
    }

    // Measurement destination address selected by +v-cold-dst.  Warm-up
    // deliberately keeps using the original V_DST_IOVA/V_DST_PA.
    uint64_t v_measure_dst_iova() const {
        return v_cold_dst ? V_COLD_DST_IOVA : V_DST_IOVA;
    }
    uint64_t v_measure_dst_pa() const {
        return v_cold_dst ? V_COLD_DST_PA : V_DST_PA;
    }

    // program ONE batch-off 64-bit copy
    void program_single(bool sel, uint64_t src, uint64_t dst) {
        cfg_wr(sel, REG_CONF, 0x0);
        cfg_wr(sel, REG_SRC,  src);
        cfg_wr(sel, REG_DST,  dst);
        cfg_wr(sel, REG_NB,   (uint64_t)PAGE_BYTES);
    }

    // Read NEXT_ID (0x28) to issue the programmed transfer and return the
    // reserved functional ID so DONE can be matched exactly.
    uint64_t trigger(bool sel) {
        return cfg_rd(sel, REG_NEXT);
    }

    // Poll DONE (0x30) until it equals the ID reserved by trigger().
    void wait_done(bool sel, uint64_t expected, const char* where) {
        long t = 0;
        for (; t < WATCHDOG_CYCLES; ++t) {
            tick();
            if (g_cycle - last_progress_cycle > WATCHDOG_CYCLES) {
                dump_stall(where);
                throw TestFailure("watchdog: no handshake progress while waiting DONE");
            }
            if (g_cycle - scenario_start > scenario_budget) {
                dump_stall(where);
                throw TestFailure("scenario budget exhausted while waiting DONE");
            }
            uint64_t d = cfg_rd(sel, REG_DONE);
            if (d == expected) return;
        }
        dump_stall(where);
        throw TestFailure("DONE never reached the expected ID");
    }

